import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

// Both collections are generated by `npm run sync` from the Obsidian vault.

/** Ids look like `traitors-tome/en/18` or `secrets-of-survival/ru/09-12`. */
const haunts = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/haunts' }),
  schema: z.object({
    title: z.string(),
    titleEn: z.string().optional(),
    number: z.number().int(),
    lastNumber: z.number().int().optional(),
    stub: z.boolean(),
    scenarioCard: z.string().optional(),
    trigger: z.string().optional(),
    traitor: z.string().optional(),
  }),
});

/** Ids look like `en/terms`. */
const pages = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/pages' }),
  schema: z.object({
    title: z.string(),
  }),
});

export const collections = { haunts, pages };
